#include <stdio.h>
int main(void)
{
  int year;
  scanf("%d", &year);
  if ((year % 4 == 0 && year % 100 != 0) || year % 400 == 0)
    printf("%d is a leap year\n", year);
  else
    printf("%d is not a leap year\n", year);
  return 0;
}

#include <stdio.h>
int main(void)
{
  int m, n, a, b, r;
  scanf("%d%d", &m, &n);
  a = m;
  b = n;
  while (b != 0) {
    r = a % b;
    a = b;
    b = r;
  }
  printf("gcd=%d, lcm=%d\n", a, m / a * n);
  return 0;
}

#include <stdio.h>
#include <math.h>
int main(void)
{
  int sign = 1;
  double n = 1.0, term = 1.0, sum = 0;
  while (fabs(term) >= 1e-6) {
    sum += term;
    n += 2;
    sign = -sign;
    term = sign / n;
  }
  printf("pi=%f\n", sum * 4);
  return 0;
}

