#include <stdio.h>
int main(void)
{
  int a[10], i, j, k, t;
  for (i = 0; i < 10; i++)
    scanf("%d", &a[i]);
  for (i = 0; i < 9; i++) {
    k = i;
    for (j = i + 1; j < 10; j++)
      if (a[j] < a[k])
        k = j;
    if (k != i) {
      t = a[i]; a[i] = a[k]; a[k] = t;
    }
  }
  for (i = 0; i < 10; i++)
    printf("%d ", a[i]);
  printf("\n");
  return 0;
}

#include <stdio.h>
int main(void)
{
  int c, letter = 0, digit = 0, space = 0, other = 0;
  while ((c = getchar()) != '\n') {
    if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
      letter++;
    else if (c >= '0' && c <= '9')
      digit++;
    else if (c == ' ')
      space++;
    else
      other++;
  }
  printf("letter=%d digit=%d space=%d other=%d\n",
         letter, digit, space, other);
  return 0;
}

