int main(void)
{
  char s[81];
  int i, j, flag = 1;
  scanf("%s", s);
  i = 0;
  j = strlen(s) - 1;
  while (i < j) {
    if (s[i] != s[j]) {
      flag = 0;
      break;
    }
    i++;
    j--;
  }
