#include <stdio.h>
double average(int a[], int n)
{
  int i, s = 0;
  for (i = 0; i < n; i++)
    s += a[i];
  return (double)s / n;
}
int main(void)
{
  int a[10], i, cnt = 0;
  double avg;
  for (i = 0; i < 10; i++)
    scanf("%d", &a[i]);
  avg = average(a, 10);
  for (i = 0; i < 10; i++)
    if (a[i] > avg)
      cnt++;
  printf("avg=%.2f, count=%d\n", avg, cnt);
  return 0;
}

#include <stdio.h>
void mystrcat(char *s, char *t)
{
  while (*s != '\0')
    s++;
  while (*t != '\0') {
    *s = *t;
    s++;
    t++;
  }
  *s = '\0';
}
int main(void)
{
  char a[100], b[50];
  scanf("%s%s", a, b);
  mystrcat(a, b);
  printf("%s\n", a);
  return 0;
}

#include <stdio.h>
int fib(int n)
{
  if (n == 1 || n == 2)
    return 1;
  return fib(n - 1) + fib(n - 2);
}
int main(void)
{
  int i;
  for (i = 1; i <= 10; i++)
    printf("%d ", fib(i));
  printf("\n");
  return 0;
}

#include <stdio.h>
struct student {
  int num;
  char name[20];
  int score;
};
int main(void)
{
  struct student s[30], t;
  int n, i, j;
  scanf("%d", &n);
  for (i = 0; i < n; i++)
    scanf("%d%s%d", &s[i].num, s[i].name, &s[i].score);
  for (i = 0; i < n - 1; i++)
    for (j = 0; j < n - 1 - i; j++)
      if (s[j].score < s[j + 1].score) {
        t = s[j]; s[j] = s[j + 1]; s[j + 1] = t;
      }
  for (i = 0; i < n; i++)
    printf("%d %s %d\n", s[i].num, s[i].name, s[i].score);
  return 0;
}

#include <stdio.h>
#include <stdlib.h>
int main(void)
{
  FILE *fp;
  int c;
  if ((fp = fopen("upper.txt", "w")) == NULL) {
    printf("cannot open file\n");
    exit(1);
  }
  while ((c = getchar()) != '\n') {
    if (c >= 'a' && c <= 'z')
      c = c - 32;
    fputc(c, fp);
  }
  fclose(fp);
  fp = fopen("upper.txt", "r");
  while ((c = fgetc(fp)) != EOF)
    putchar(c);
  putchar('\n');
  fclose(fp);
  return 0;
}
